ALTER TABLE marketplaces DROP CONSTRAINT marketplaces_id_check;
ALTER TABLE marketplaces ADD COLUMN website_url TEXT NOT NULL DEFAULT '';
ALTER TABLE marketplaces ADD COLUMN allowed_hosts TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE marketplaces ADD COLUMN scraping_enabled BOOLEAN NOT NULL DEFAULT true;
UPDATE marketplaces SET website_url='https://www.amazon.com.br',allowed_hosts=ARRAY['www.amazon.com.br','amazon.com.br','m.amazon.com.br','amzn.to','a.co'] WHERE id='amazon';
UPDATE marketplaces SET website_url='https://www.mercadolivre.com.br',allowed_hosts=ARRAY['www.mercadolivre.com.br','mercadolivre.com.br','meli.la'] WHERE id='mercadolivre';
UPDATE marketplaces SET website_url='https://shopee.com.br',allowed_hosts=ARRAY['shopee.com.br','www.shopee.com.br','s.shopee.com.br','shope.ee'] WHERE id='shopee';
CREATE TABLE scraping_profiles (
 marketplace_id TEXT PRIMARY KEY REFERENCES marketplaces(id) ON DELETE CASCADE,
 rules JSONB NOT NULL, wait_timeout_ms INTEGER NOT NULL DEFAULT 15000,
 validity_minutes INTEGER NOT NULL DEFAULT 360,
 version INTEGER NOT NULL DEFAULT 1, updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE offers DROP CONSTRAINT offers_source_check;
ALTER TABLE offers ADD CONSTRAINT offers_source_check CHECK(source IN ('api','manual','scraped'));
ALTER TABLE offers ADD COLUMN images JSONB NOT NULL DEFAULT '[]';
ALTER TABLE offers ADD COLUMN specifications JSONB NOT NULL DEFAULT '[]';
ALTER TABLE offers ADD COLUMN extraction_metadata JSONB NOT NULL DEFAULT '{}';
CREATE TABLE offer_import_previews (
 id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 marketplace_id TEXT NOT NULL REFERENCES marketplaces(id) ON DELETE CASCADE,
 affiliate_url TEXT NOT NULL, source_url TEXT NOT NULL, result JSONB NOT NULL,
 profile_version INTEGER NOT NULL, expires_at TIMESTAMPTZ NOT NULL,
 offer_id UUID REFERENCES offers(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX offer_import_previews_expiry_idx ON offer_import_previews(expires_at);
INSERT INTO scraping_profiles(marketplace_id,rules) VALUES('amazon','[{"field": "title", "selectors": ["#productTitle"], "mode": "text", "attribute": "", "required": true}, {"field": "price", "selectors": ["#corePriceDisplay_desktop_feature_div [data-csa-c-price-to-pay]"], "mode": "attribute", "attribute": "data-csa-c-price-to-pay", "required": true}, {"field": "price", "selectors": ["#corePriceDisplay_desktop_feature_div .priceToPay", ".apex-pricetopay-value"], "mode": "text", "attribute": "", "required": false}, {"field": "originalPrice", "selectors": ["#corePriceDisplay_desktop_feature_div [data-csa-c-strike-through-price]"], "mode": "attribute", "attribute": "data-csa-c-strike-through-price", "required": false}, {"field": "originalPrice", "selectors": ["#corePriceDisplay_desktop_feature_div .apex-basisprice-value"], "mode": "text", "attribute": "", "required": false}, {"field": "images", "selectors": ["#landingImage", "#imgBlkFront"], "mode": "attribute", "attribute": "data-old-hires", "required": false}, {"field": "images", "selectors": ["#landingImage", "#imgBlkFront"], "mode": "attribute", "attribute": "src", "required": false}, {"field": "images", "selectors": ["#landingImage"], "mode": "attribute", "attribute": "data-a-dynamic-image", "required": false}, {"field": "description", "selectors": ["#productDescription", "#feature-bullets"], "mode": "text", "attribute": "", "required": false}, {"field": "specifications", "selectors": ["#productDetails_techSpec_section_1 tr", "#productDetails_detailBullets_sections1 tr"], "mode": "pairs", "attribute": "", "required": false, "nameSelector": "th", "valueSelector": "td"}, {"field": "externalId", "selectors": ["input#ASIN"], "mode": "attribute", "attribute": "value", "required": false}]');
INSERT INTO scraping_profiles(marketplace_id,rules) VALUES('mercadolivre','[{"field": "title", "selectors": ["h1.ui-pdp-title"], "mode": "text", "attribute": "", "required": true}, {"field": "title", "selectors": ["meta[property=\"og:title\"]"], "mode": "attribute", "attribute": "content", "required": false}, {"field": "price", "selectors": [".ui-pdp-price__second-line .andes-money-amount", ".poly-price__current .andes-money-amount"], "mode": "text", "attribute": "", "required": true}, {"field": "originalPrice", "selectors": [".ui-pdp-price__original-value", ".poly-component__price .andes-money-amount--previous"], "mode": "text", "attribute": "", "required": false}, {"field": "images", "selectors": [".ui-pdp-gallery__figure img"], "mode": "attribute", "attribute": "data-zoom", "required": false}, {"field": "images", "selectors": [".ui-pdp-gallery__figure img", "meta[property=\"og:image\"]"], "mode": "attribute", "attribute": "content", "required": false}, {"field": "images", "selectors": [".ui-pdp-gallery__figure img"], "mode": "attribute", "attribute": "src", "required": false}, {"field": "description", "selectors": [".ui-pdp-description__content"], "mode": "text", "attribute": "", "required": false}, {"field": "specifications", "selectors": [".ui-pdp-specs__table tr"], "mode": "pairs", "attribute": "", "required": false, "nameSelector": "th", "valueSelector": "td"}, {"field": "conditions", "selectors": [".ui-pdp-price__subtitles", ".poly-component__price"], "mode": "text", "attribute": "", "required": false}, {"field": "productUrl", "selectors": ["a[href*=\"pdp_filters=item_id\"]"], "mode": "attribute", "attribute": "href", "required": false}]');
INSERT INTO scraping_profiles(marketplace_id,rules) VALUES('shopee','[{"field": "title", "selectors": ["h1"], "mode": "text", "attribute": "", "required": true}, {"field": "price", "selectors": ["[data-testid=\"product-price\"]"], "mode": "text", "attribute": "", "required": true}, {"field": "images", "selectors": ["meta[property=\"og:image\"]"], "mode": "attribute", "attribute": "content", "required": false}, {"field": "description", "selectors": ["[data-testid=\"product-description\"]"], "mode": "text", "attribute": "", "required": false}]');
